    var giacu = el.innerHTML.substring(el.innerHTML.indexOf("[giacu]") + 7, el.innerHTML.indexOf("[/giacu]"));
    var hotdeal = el.innerHTML.substring(el.innerHTML.indexOf("[hot]") + 5, el.innerHTML.indexOf("[/hot]"));

