// 3. Hàm Tour liên quan (relatedproduct)
function relatedproduct(e) {
    if (!e || !e.feed || !e.feed.entry) return;
    var container = document.getElementById("related-products-box");
    var html = "";
    var max = Math.min(e.feed.entry.length, 4);
    for (var n = 0; n < max; n++) {
        var r = e.feed.entry[n], i = r.title.$t, o = "";
        for (var u = 0; u < r.link.length; u++) if ("alternate" == r.link[u].rel) { o = r.link[u].href; break; }
        var t = "content" in r ? r.content.$t : "summary" in r ? r.summary.$t : "";
        var giaban = t.indexOf("[giaban]") != -1 ? t.substring(t.indexOf("[giaban]") + 8, t.indexOf("[/giaban]")) : "";
        var giacu = t.indexOf("[giacu]") != -1 ? t.substring(t.indexOf("[giacu]") + 7, t.indexOf("[/giacu]")) : "";
        var imgSrc = "";
        var a = t.indexOf("<img"), b = t.indexOf('src="', a), c = t.indexOf('"', b + 5);
        if (-1 != a && -1 != b && -1 != c) imgSrc = t.substr(b + 5, c - b - 5);

        html += '<div class="col-xs-6 col-sm-4 col-lg-3">' +
            '<div class="product-box simpleCart_shelfItem">' +
                '<div class="product-thumbnail">' +
                    '<a href="' + o + '" title="' + i + '"><picture><img src="' + imgSrc + '" alt="' + i + '" class="item_thumb" loading="lazy" decoding="async"/></picture></a>' +
                '</div>' +
                '<div class="product-info">' +
                    '<h3 class="product-name"><a href="' + o + '" title="' + i + '" class="item_name">' + i + '</a></h3>' +
                    '<div class="price-box clearfix">' +
                        '<div class="special-price"><span class="price product-price item_price">' + giaban + '</span></div>' +
                        '<div class="old-price"><span class="price product-price-old">' + giacu + '</span></div>' +
                    '</div>' +
                '</div>' +
            '</div></div>';
    }
    if (container) container.innerHTML = html;
    else document.write(html);
}

// 4. Hàm labelproduct
function labelproduct(e) {
    if (!e || !e.feed || !e.feed.entry) return;
    var html = "";
    var max = Math.min(e.feed.entry.length, 20);
    for (var t = 0; t < max; t++) {
        var n = e.feed.entry[t], r = n.title.$t, i = "";
        for (var o = 0; o < n.link.length; o++) if ("alternate" == n.link[o].rel) { i = n.link[o].href; break; }
        var c = "content" in n ? n.content.$t : "summary" in n ? n.summary.$t : "";
        var giaban = -1 != c.indexOf("[giaban]") ? c.substring(c.indexOf("[giaban]") + 8, c.indexOf("[/giaban]")) : "";
        var giacu = -1 != c.indexOf("[giacu]") ? c.substring(c.indexOf("[giacu]") + 7, c.indexOf("[/giacu]")) : "";
        var hangsx = -1 != c.indexOf("[hangsx]") ? c.substring(c.indexOf("[hangsx]") + 8, c.indexOf("[/hangsx]")) : "";
        var imgSrc = "";
        var a = c.indexOf("<img"), b = c.indexOf('src="', a), d = c.indexOf('"', b + 5);
        if (-1 != a && -1 != b && -1 != d) imgSrc = c.substr(b + 5, d - b - 5);

        html += '<div class="col-lg-2 col-xs-6 col-sm-4 col-md-3"><div class="product-box">' +
            '<div class="product-thumbnail"><a href="' + i + '" title="' + r + '"><picture><img src="' + imgSrc + '" alt="' + r + '" class="img-responsive center-block" loading="lazy" decoding="async"/></picture></a></div>' +
            '<div class="product-info"><p class="p-vendor">' + hangsx + '</p><h3 class="product-name"><a href="' + i + '" title="' + r + '">' + removeHtmlTag(r, 40) + '</a></h3>' +
            '<div class="price-box clearfix"><div class="special-price"><span class="price product-price">' + giaban + '</span></div><div class="old-price"><span class="price product-price-old">' + giacu + '</span></div></div>' +
            '</div></div></div>';
    }
    document.write(html);
}

