// 6. Hàm labeltintuc
function labeltintuc(e) {
    if (!e || !e.feed || !e.feed.entry) return;
    var html = "";
    var max = Math.min(e.feed.entry.length, 5);
    for (var t = 0; t < max; t++) {
        var r = e.feed.entry[t], o = r.title.$t, n = "";
        for (var l = 0; l < r.link.length; l++) if ("alternate" == r.link[l].rel) { n = r.link[l].href; break; }
        var u = "content" in r ? r.content.$t : "summary" in r ? r.summary.$t : "";
        var imgSrc = "";
        var a = u.indexOf("<img"), b = u.indexOf('src="', a), d = u.indexOf('"', b + 5);
        if (-1 != a && -1 != b && -1 != d) imgSrc = u.substr(b + 5, d - b - 5);
        var postdate = r.published.$t.substring(0, 10);

        html += '<article class="blog-item blog-item-list col-md-12"><a href="' + n + '" class="panel-box-media"><img src="' + imgSrc + '" width="70" height="70" alt="' + o + '" loading="lazy" decoding="async"></a>' +
            '<div class="blogs-rights"><h3 class="blog-item-name"><a href="' + n + '" title="' + o + '">' + o + '</a></h3><div class="post-time">' + postdate + '</div></div></article>';
    }
    document.write(html);
}

